import React, {CSSProperties, FC, ReactNode, forwardRef, useEffect, useRef} from 'react';

import {InternalError, NotFound} from '@gravity-ui/illustrations';
import {
    Icon,
    List,
    ListItemData,
    Loader,
    PlaceholderContainer,
    PlaceholderContainerActionProps,
    Popup,
    PopupPlacement,
    PopupProps,
    TextInput,
    TextInputPin,
    TextInputProps,
    TextInputSize,
    getConfig,
    setRef,
} from '@gravity-ui/uikit';
import type {DOMProps, QAProps} from '@gravity-ui/uikit';
import debounce from 'lodash/debounce';
import noop from 'lodash/noop';
import _sortBy from 'lodash/sortBy';
import throttle from 'lodash/throttle';
import uniqueId from 'lodash/uniqueId';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {OutsideFocusHandlerContainer} from '../useOnFocusOutside/OutsideFocusHandlerContainer';

import {cnSuggest} from './Suggest.classname';
import {defaultMessages} from './i18n';

import './Suggest.scss';

export type RenderStyle = 'popup' | 'inline';

export type RenderFallbackContentProps = {
    text: string;
    error?: Error | null;
};

export interface SuggestProps<T = any> extends DOMProps, QAProps {
    /** Текст в поле ввода */
    text: string;
    /** Функция, реагирующая на изменения текста `text` в поле ввода */
    onUpdate: (item: string) => void;
    /** Функция, принимающая текст из поля ввода и возвращающая новый список элементов саджеста или `Promise` */
    getItems: (text: string) => ListItemData<T>[] | Promise<ListItemData<T>[]>;
    /** Обработчик клика по элементу саджеста */
    onItemClick?: (item: T, index?: number, fromKeyboard?: boolean) => boolean | void;
    /** Функция для кастомного лейаута саджеста. */
    children?: (input: ReactNode, items: ListItemData<T>[], loading: boolean) => ReactNode;
    /** Placeholder поля ввода */
    placeholder?: string;
    /** Сделать поле ввода неактивным */
    disabled?: boolean;
    /** Атрибут `autocomplete` поля ввода */
    autoComplete?: TextInputProps['autoComplete'];
    /** Включить автофокус поля ввода */
    autoFocus?: boolean;
    popupPlacement?: PopupPlacement;
    /** Микс для имени класса попапа */
    popupClassName?: string;
    /** Отключает floating-ui портал попапа */
    popupDisablePortal?: boolean;
    /** Микс для имени класса импута */
    inputClassName?: string;
    /** Высота элемента саджеста в `px` или функция, возвращающая значение высоты для элемента саджеста: `(item: any) => number`. Используется только при `virtualized: true`. */
    itemHeight?: number | ((item: ListItemData<T>) => number);
    /** Флаг, указывающий, что значение из поля ввода должно быть обработано, и не обязательно должен быть выбран элемент из саджеста. Должен быть указан `onInputEnterKeyDown`. */
    applicableInputValue?: boolean;
    /** Запрашивать список элементов саджеста при начальной отрисовке компонента */
    getItemsOnMount?: boolean;
    /** Показывать элементы саджеста при пустом поле ввода */
    showItemsOnNoText?: boolean;
    /** Обработчик нажатия Tab в поле ввода или на элемент списка. Используется только при открытом попапе саджеста */
    onTabKeyDown?: (
        text: string,
        event: React.KeyboardEvent,
        extra: {
            items: ListItemData<T>[];
            activeItem: number | undefined;
        },
    ) => boolean | undefined;
    /** Обработчик нажатия Enter в поле ввода. Если не указан, то по Enter будет срабатывать `onItemClick` на активном элементе саджеста. Используется только при `applicableInputValue: true`. */
    onInputEnterKeyDown?: (text: string, event: React.KeyboardEvent) => void;
    /** Обработчик нажатия любой клавиши в поле ввода */
    onInputKeyDown?: (text: string, event: React.KeyboardEvent) => void;
    /** Функция, которая будет вызвана на блюр текстового инпута */
    onBlur?: () => void;
    /** Функция, которая будет вызвана при открытии или закрытии попапа */
    onOpenChange?: (isOpen: boolean) => void;
    /** Включить синхронизацию ширины поля ввода и попапа саджеста при ресайзе окна */
    syncPopupOnResize?: boolean;
    /** Выключить показ сообщение об отсутствии совпадений */
    showNoItemsMessage?: boolean;
    /** Размер поля ввода */
    size?: TextInputSize;
    /** Включить виртуализацию. При выключенном флаге будут отрисованы все элементы саджеста разом. */
    virtualized?: boolean;
    /** Функция рендера, получающая на вход элемент саджеста и возвращающая React-ноду */
    renderItem?: (item: T) => ReactNode;
    /** Время в мс для отложенного вызова `getItems` после `onUpdate` */
    debounce?: number;
    /** Значение пробрасывается в TextInput.props.pin */
    pin?: TextInputPin;
    id?: string;
    renderStyle?: RenderStyle;
    /** Кнопка очистки инпута */
    hasClear?: boolean;
    /** Функция, высчитывающая какой Item сделать активным после резолва getItems */
    getInitialActiveItemIndex?: (items: ListItemData<T>[]) => number;
    /** Значение пробрасывается в TextInput.props.error */
    error?: TextInputProps['error'];
    /** Значение пробрасывается в TextInput.props.errorPlacement */
    errorPlacement?: TextInputProps['errorPlacement'];
    /** Значение пробрасывается в Popup.props.offset */
    popupOffset?: PopupProps['offset'];
    /** Генератор кастомного сообщения о пустом списке элементов на основе текущего значения поля ввода */
    /**
     * @deprecated use renderEmptyResultFallbackContent
     */
    getNoItemsMessage?: (text: string) => ReactNode;
    /** Генератор кастомного сообщения о пустом списке элементов на основе текущего значения поля ввода */
    renderEmptyResult?: FC<RenderFallbackContentProps>;
    /** Генератор кастомного сообщения об ошибке загрузки данных */
    renderFetchItemsError?: FC<RenderFallbackContentProps>;
    /** Дополнительные пропсы для контрола */
    controlProps?: React.InputHTMLAttributes<HTMLInputElement>;
    /** Нода, которая рендерится перед инпутом внутри TextInput */
    startContent?: ReactNode;
    /** Нода, которая рендерится после инпута и кнопки очистки внутри TextInput */
    endContent?: ReactNode;
    /** Ссылка для доступа к TextInput */
    controlRef?: TextInputProps['controlRef'];
}

interface SuggestState<T> {
    progress: boolean;
    focused: boolean;
    items: ListItemData<T>[];
    progressTimerId: ReturnType<typeof setTimeout> | null;
    activeIndex?: number;
    fetchError: Error | null;
    showEmptyMessage: boolean;
}

interface SuggestLocalizationProps {
    t: (key: string, params?: Record<string, unknown>) => string;
}

interface PopupWrapperProps {
    open: boolean;
    /** Функция, которая будет вызвана при открытии или закрытии попапа */
    onOpenChange?: (isOpen: boolean) => void;
    /** Контент попапа */
    children?: React.ReactNode;
}

const PopupWrapper: React.FC<PopupWrapperProps> = ({open, onOpenChange = noop, children}) => {
    const isFirstRender = useRef(true);

    useEffect(() => {
        if (isFirstRender.current) {
            isFirstRender.current = false;
        } else {
            onOpenChange(open);
        }
    }, [onOpenChange, open]);

    return children;
};

export class SuggestView<T = any> extends React.PureComponent<
    SuggestProps<T> & SuggestLocalizationProps,
    SuggestState<T>
> {
    static defaultProps: Partial<SuggestProps> = {
        virtualized: false,
        renderItem: (item) => item,
        debounce: 0,
        renderStyle: 'popup',
    };

    static getDerivedStateFromProps<Props extends SuggestProps>(nextProps: Props) {
        if (!nextProps.showItemsOnNoText && !nextProps.text) {
            return {
                items: [],
            };
        }

        return null;
    }

    state: SuggestState<T> = {
        progress: false,
        focused: false,
        items: [],
        progressTimerId: null,
        fetchError: null,
        showEmptyMessage: false,
    };

    throttledForceUpdate = throttle(() => this.forceUpdate(), 300);

    textInputRef = React.createRef<HTMLInputElement>();
    inputRef = React.createRef<HTMLDivElement>();

    listRef = React.createRef<List<T>>();

    latestPromise?: Promise<T[]>;

    _getItems = debounce(async (text: string) => {
        let items: ListItemData<T>[] = [];
        const result = this.props.getItems(text);
        if (result instanceof Promise) {
            this.latestPromise = result;
        }

        try {
            items = await result;
            this.setState({fetchError: null});
        } catch (error) {
            this.setState({fetchError: error as Error});
        }

        if (result instanceof Promise) {
            // Exit if this promise is different of the latest one
            if (result !== this.latestPromise) {
                return;
            }

            delete this.latestPromise;
        }

        this.setState({
            items,
            showEmptyMessage: !items?.length,
        });
        this.clearProgress();
        if (items.length && !this.props.applicableInputValue) {
            if (this.props.getInitialActiveItemIndex) {
                const index = this.props.getInitialActiveItemIndex(items) || 0;
                this.setState({activeIndex: index});
            } else if (this.listRef.current) {
                const keyDownEvent = new KeyboardEvent('keydown', {key: 'ArrowDown'});
                this.listRef.current.onKeyDown(
                    keyDownEvent as unknown as React.KeyboardEvent<HTMLDivElement>,
                );
            }
        }
    }, this.props.debounce);

    componentDidMount() {
        const {getItemsOnMount, text} = this.props;
        if (this.props.syncPopupOnResize) {
            window.addEventListener('resize', this.throttledForceUpdate);
        }
        if (getItemsOnMount) {
            this.getItems(text);
        }
    }

    componentDidUpdate(prevProps: SuggestProps): void {
        const {text, showItemsOnNoText} = this.props;
        if (text !== prevProps.text && (text || showItemsOnNoText)) {
            this.getItems(text);
        }
    }

    componentWillUnmount() {
        window.removeEventListener('resize', this.throttledForceUpdate);
        this.clearProgress();
    }

    render() {
        const {
            text,
            size,
            className,
            popupClassName,
            popupPlacement,
            popupDisablePortal,
            disabled,
            autoComplete,
            autoFocus,
            placeholder,
            onBlur,
            onOpenChange,
            pin,
            id,
            renderStyle,
            hasClear,
            children,
            inputClassName,
            error,
            errorPlacement,
            popupOffset,
            applicableInputValue,
            controlProps,
            startContent,
            endContent,
            style,
            qa,
        } = this.props;
        const {progress, items, focused} = this.state;

        const input = (
            <TextInput
                size={size}
                value={text}
                placeholder={placeholder}
                disabled={disabled}
                autoComplete={autoComplete}
                autoFocus={autoFocus}
                ref={this.inputRef}
                controlRef={this.updateTextInputRef}
                onBlur={onBlur}
                onUpdate={this.onUpdate}
                onFocus={() => this.setState({focused: true})}
                onKeyDown={this.onInputKeyDown}
                className={cnSuggest('input', inputClassName)}
                pin={pin}
                id={id}
                hasClear={hasClear}
                error={error}
                errorPlacement={errorPlacement}
                qa={qa}
                style={style}
                controlProps={{
                    role: 'combobox',
                    'aria-controls': `popup-${id}`,
                    'aria-autocomplete': applicableInputValue ? 'both' : 'list',
                    'aria-expanded': this.isPopupHasContent() && this.state.focused,
                    'aria-activedescendant':
                        this.state.activeIndex === undefined
                            ? undefined
                            : `${id}-list-item-${this.state.activeIndex}`,
                    ...controlProps,
                }}
                startContent={startContent}
                endContent={endContent}
            />
        );

        if (children) {
            return React.createElement(React.Fragment, undefined, children(input, items, progress));
        }

        return (
            <OutsideFocusHandlerContainer
                as="div"
                className={cnSuggest(null, className)}
                enable={focused}
                onFocusOutside={this.handleClosePopup}
            >
                {input}
                <PopupWrapper
                    open={renderStyle === 'popup' && this.isPopupHasContent() && this.state.focused}
                    onOpenChange={onOpenChange}
                >
                    {this.isPopupHasContent() &&
                        (renderStyle === 'inline' ? (
                            <div className={cnSuggest('inline-content')}>
                                {this.renderPopupContent()}
                            </div>
                        ) : (
                            <Popup
                                key={items?.length}
                                open={this.isPopupHasContent() && this.state.focused}
                                className={cnSuggest(
                                    'popup',
                                    {
                                        'has-fallback':
                                            Boolean(this.state.fetchError) || !items.length,
                                    },
                                    popupClassName,
                                )}
                                style={
                                    this.inputRef.current
                                        ? {width: this.inputRef.current.offsetWidth}
                                        : {}
                                }
                                anchorElement={this.inputRef.current}
                                placement={popupPlacement}
                                id={`popup-${id}`}
                                onOutsideClick={this.handleClosePopup}
                                onEscapeKeyDown={this.handleClosePopup}
                                returnFocus={false}
                                disablePortal={popupDisablePortal}
                                offset={popupOffset}
                            >
                                {this.renderPopupContent()}
                            </Popup>
                        ))}
                </PopupWrapper>
            </OutsideFocusHandlerContainer>
        );
    }

    renderIllustration(type: '404' | '500') {
        switch (type) {
            case '404':
                return NotFound;
            case '500':
            default:
                return InternalError;
        }
    }

    getItems(text: string) {
        this.setProgressWithDelay();
        this.setState({activeIndex: undefined, fetchError: null, showEmptyMessage: false});
        this._getItems(text);
    }

    private setProgressWithDelay() {
        if (!this.state.progressTimerId) {
            this.setState({
                progressTimerId: setTimeout(() => this.setState({progress: true}), 300),
            });
        }
    }

    private clearProgress() {
        const {progressTimerId} = this.state;

        this.setState({progress: false});
        if (progressTimerId) {
            clearTimeout(progressTimerId);
            this.setState({progressTimerId: null});
        }
    }

    private handleClosePopup = () => {
        this.setState((state) => {
            return state.focused ? {focused: false} : null;
        });
    };

    private renderItem = (item: T, _active: boolean, index: number) => (
        <div key={index} className={cnSuggest('item')}>
            {this.props.renderItem!(item)}
        </div>
    );

    private onItemClick = (item: T, index?: number, fromKeyboard?: boolean) => {
        let focused = false;
        if (this.props.onItemClick) {
            focused = Boolean(this.props.onItemClick(item, index, fromKeyboard));
        }
        this.setState({focused});
    };

    private onChangeActive = (index?: number) => {
        this.setState({activeIndex: index});
    };

    private renderDefaultPopupFallback({
        type,
        renderFallbackContent: RenderFallbackContent,
        title,
        description,
        buttonText,
    }: {
        type: '404' | '500';
        renderFallbackContent?: FC<RenderFallbackContentProps> | null;
        title?: string;
        description?: string;
        buttonText?: string;
    }) {
        const {text} = this.props;
        const {fetchError} = this.state;

        if (typeof RenderFallbackContent === 'function') {
            return (
                <div className={cnSuggest('list', {empty: true})}>
                    <RenderFallbackContent text={text} error={fetchError} />
                </div>
            );
        }

        const actions: PlaceholderContainerActionProps[] = buttonText
            ? [
                  {
                      text: buttonText,
                      view: 'action',
                      onClick: () => this.getItems(text),
                  },
              ]
            : [];

        return (
            <PlaceholderContainer
                title={title}
                description={description}
                direction="row"
                size="s"
                align="center"
                image={<Icon data={this.renderIllustration(type)} size={100} />}
                actions={actions}
            />
        );
    }

    private getRenderFallbackContent() {
        const {renderEmptyResult, getNoItemsMessage} = this.props;
        if (renderEmptyResult) {
            return renderEmptyResult;
        }

        if (getNoItemsMessage) {
            return ({text}: RenderFallbackContentProps) => getNoItemsMessage?.(text);
        }

        return null;
    }

    private renderPopupContent() {
        const {text, virtualized, itemHeight, id, renderFetchItemsError} = this.props;
        const {progress, items, fetchError, showEmptyMessage} = this.state;
        const {t} = this.props;

        if (progress) {
            return (
                <div className={cnSuggest('loader')}>
                    <Loader />
                </div>
            );
        }

        if (fetchError) {
            return this.renderDefaultPopupFallback({
                type: '500',
                renderFallbackContent: renderFetchItemsError,
                title: t('fetch_error_title'),
                description: t('fetch_error_description'),
                buttonText: t('retry'),
            });
        }

        if (items.length) {
            const style: CSSProperties = {};

            if (virtualized) {
                let height = 0;

                if (typeof itemHeight === 'function') {
                    items.forEach((item) => {
                        height += itemHeight(item);
                    });
                }

                if (typeof itemHeight === 'number') {
                    height = items.length * itemHeight;
                }

                if (height) {
                    style.height = height;
                }
            }

            return (
                <div className={cnSuggest('list')} style={style}>
                    <List
                        filterable={false}
                        items={items}
                        renderItem={this.renderItem}
                        onItemClick={this.onItemClick}
                        virtualized={virtualized}
                        itemHeight={itemHeight}
                        ref={this.listRef}
                        id={`${id}-list`}
                        role={'listbox'}
                        onChangeActive={this.onChangeActive}
                        activeItemIndex={this.state.activeIndex}
                    />
                </div>
            );
        }

        if (showEmptyMessage && text) {
            return this.renderDefaultPopupFallback({
                type: '404',
                renderFallbackContent: this.getRenderFallbackContent(),
                title: t('items_not_found_title'),
                description: t('items_not_found', {text}),
            });
        }

        return null;
    }

    private onUpdate = (text: string) => {
        const {onUpdate, showItemsOnNoText} = this.props;
        onUpdate(text);

        if (text && !this.state.focused) {
            this.setState({focused: true});
        }

        if (showItemsOnNoText || text) {
            this.getItems(text);
        }
    };

    private isPopupHasContent() {
        const {progress, items, fetchError, showEmptyMessage} = this.state;
        const {text, showNoItemsMessage = true} = this.props;

        return Boolean(
            progress ||
            items.length ||
            fetchError ||
            (text && showEmptyMessage && showNoItemsMessage),
        );
    }

    private onInputKeyDown = (event: React.KeyboardEvent) => {
        if (
            typeof this.props.onTabKeyDown === 'function' &&
            event.key === 'Tab' &&
            this.listRef.current
        ) {
            const activeItemIndex = this.listRef.current.getActiveItem() ?? undefined;

            const focused = this.props.onTabKeyDown(this.props.text, event, {
                items: this.state.items,
                activeItem: activeItemIndex,
            });
            if (this.state.focused !== focused && typeof focused === 'boolean') {
                this.setState({focused});
            }
        }
        if (
            typeof this.props.onInputKeyDown === 'function' &&
            (!this.listRef.current || typeof this.listRef.current.getActiveItem() !== 'number')
        ) {
            this.props.onInputKeyDown(this.props.text, event);
        }

        if (
            event.key === 'Enter' &&
            this.props.applicableInputValue &&
            typeof this.props.onInputEnterKeyDown === 'function' &&
            (!this.listRef.current || typeof this.listRef.current.getActiveItem() !== 'number')
        ) {
            this.props.onInputEnterKeyDown(this.props.text, event);
        } else if (this.listRef.current) {
            this.listRef.current.onKeyDown(event as React.KeyboardEvent<HTMLDivElement>);
        }
        // Prevent outside form submission on Enter if Popup is opened. In order to submit the form, User has
        // to press Enter twice - first to select item and close the Popup, then to submit.
        if (event.key === 'Enter' && this.state.focused) {
            event.preventDefault();
        }

        if (event.key === 'Home' || event.key === 'End') {
            // List component calls event.preventDefault() as result TextInput ignores Home/End hits
            // and cursor is not moved appropriately, so we have to manage it manually
            this.moveCursorToEdge(event.key === 'Home', event.shiftKey);
            event.preventDefault();
        }
    };

    private moveCursorToEdge(moveToStart: boolean, selectMode: boolean) {
        if (!this.textInputRef.current) {
            return;
        }

        const input = this.textInputRef.current;
        const end = moveToStart ? 0 : input.value.length;
        if (end == input.selectionStart) {
            return;
        }
        const selStart = input.selectionStart! >= 0 ? Number(input.selectionStart) : end;
        const start = selectMode ? selStart : end;
        const [b, e] = _sortBy([start, end]);
        input.setSelectionRange(b, e, start > end ? 'backward' : 'forward');
    }

    private updateTextInputRef = (element: HTMLInputElement | null) => {
        setRef(this.textInputRef, element);
        setRef(this.props.controlRef, element);
    };
}

const SuggestWithLocalization = <T = any,>(
    props: SuggestProps<T>,
    ref: React.ForwardedRef<SuggestView<T>>,
) => {
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);
    const {id = uniqueId('suggest-'), ...restProps} = props;

    return <SuggestView id={id} {...restProps} ref={ref} t={t} />;
};

export const Suggest = forwardRef(SuggestWithLocalization) as <T = any>(
    props: SuggestProps<T> & React.RefAttributes<SuggestView<T>>,
) => React.ReactElement;
